  /**
   * @method
   * @name digifinex#fetchOrder
   * @description fetches information on an order made by the user
   * @see https://docs.digifinex.com/en-ww/spot/v3/rest.html#get-order-status
   * @see https://docs.digifinex.com/en-ww/swap/v2/rest.html#orderinfo
   * @param {string} id order id
   * @param {string} symbol unified symbol of the market the order was made in
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {object} An [order structure]{@link
   * https://docs.ccxt.com/?id=order-structure}
   */
  std::shared_future<ccxt::any>
  fetchOrder(ccxt::any id, ccxt::any symbol = ccxt::any{},
             ccxt::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> ccxt::any {
                 if (isTrue(isEqual(this->markets, ccxt::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 ccxt::any market = ccxt::any{};
                 if (isTrue(!isEqual(symbol, ccxt::any{}))) {
                   market = this->market(symbol);
                 }
                 ccxt::any marketType = ccxt::any{};
                 ccxt::any marketTypeparamsVariable =
                     this->handleMarketTypeAndParams(std::string("fetchOrder"),
                                                     market, params);
                 marketType = ::getValue(marketTypeparamsVariable, 0);
                 params = ::getValue(marketTypeparamsVariable, 1);
                 ccxt::any marginModequeryVariable =
                     this->handleMarginModeAndParams(std::string("fetchOrder"),
                                                     params);
                 ccxt::any marginMode = ::getValue(marginModequeryVariable, 0);
                 ccxt::any query = ::getValue(marginModequeryVariable, 1);
                 ccxt::any request = ccxt::dict{
                     {std::string("order_id"), id},
                 };
                 if (isTrue(isEqual(marketType, std::string("swap")))) {
                   if (isTrue(!isEqual(market, ccxt::any{}))) {
                     ::setValue(request, std::string("instrument_id"),
                                ::getValue(market, std::string("id")));
                   }
                 } else {
                   ::setValue(request, std::string("market"), marketType);
                 }
                 ccxt::any response = ccxt::any{};
                 if (isTrue(isTrue((!isEqual(marginMode, ccxt::any{}))) ||
                            isTrue((
                                isEqual(marketType, std::string("margin")))))) {
                   marketType = std::string("margin");
                   response = awaitValue(this->privateSpotGetMarginOrder(
                       this->extend(request, query)));
                 } else if (isTrue(isEqual(marketType, std::string("spot")))) {
                   response = awaitValue(this->privateSpotGetSpotOrder(
                       this->extend(request, query)));
                 } else if (isTrue(isEqual(marketType, std::string("swap")))) {
                   response = awaitValue(this->privateSwapGetTradeOrderInfo(
                       this->extend(request, query)));
                 } else {
                   throw NotSupported(toString(
                       add(this->id,
                           std::string(
                               " fetchOrder() not support this market type"))));
                 }
                 //
                 // spot and margin
                 //
                 //     {
                 //         "code": 0,
                 //         "data": [
                 //             {
                 //                 "symbol": "BTC_USDT",
                 //                 "order_id":
                 //                 "dd3164b333a4afa9d5730bb87f6db8b3",
                 //                 "created_date": 1562303547,
                 //                 "finished_date": 0,
                 //                 "price": 0.1,
                 //                 "amount": 1,
                 //                 "cash_amount": 1,
                 //                 "executed_amount": 0,
                 //                 "avg_price": 0,
                 //                 "status": 1,
                 //                 "type": "buy",
                 //                 "kind": "margin"
                 //             }
                 //         ]
                 //     }
                 //
                 // swap
                 //
                 //     {
                 //         "code": 0,
                 //         "data": {
                 //             "order_id": "1590923061186531328",
                 //             "instrument_id": "ETHUSDTPERP",
                 //             "margin_mode": "crossed",
                 //             "contract_val": "0.01",
                 //             "type": 1,
                 //             "order_type": 0,
                 //             "price": "900",
                 //             "size": "6",
                 //             "filled_qty": "0",
                 //             "price_avg": "0",
                 //             "fee": "0",
                 //             "state": 0,
                 //             "leverage": "20",
                 //             "turnover": "0",
                 //             "has_stop": 0,
                 //             "insert_time": 1668140590372,
                 //             "time_stamp": 1668140590372
                 //         }
                 //     }
                 //
                 ccxt::any data =
                     this->safeValue(response, std::string("data"));
                 ccxt::any order =
                     (isTrue((isEqual(marketType, std::string("swap"))))
                          ? ccxt::any(data)
                          : ccxt::any(this->safeValue(data, 0)));
                 if (isTrue(isEqual(order, ccxt::any{}))) {
                   throw OrderNotFound(toString(add(
                       add(add(this->id, std::string(" fetchOrder() order ")),
                           toString(id)),
                       std::string(" not found"))));
                 }
                 return this->parseOrder(order, market);
               })
        .share();
  }

